  "type": "commonjs",
  "scripts": {
    "build": "tsc",
    "start": "node dist/index.js"
  },
  "dependencies": {
    "express": "^4.19.2",
    "express-rate-limit": "^8.6.1",
    "jsonwebtoken": "^9.0.2",
    "pg": "^8.13.1",
    "pg-format": "^1.0.4",
    "psl": "^1.9.0",
    "socket.io-client": "^4.8.3"
  },
  "devDependencies": {
    "@types/express": "^4.17.21",
    "@types/jsonwebtoken": "^9.0.7",
    "@types/node": "^20.14.10",
    "@types/pg": "^8.11.10",
    "@types/psl": "^1.1.3",
    "typescript": "^5.6.3"
  }
}
AGENT_PKG_EOF

